    <title>Terms of Use Consent</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <div id="root"></div>

    <script>
        // ConsentForm Component
        function ConsentForm() {
            const [isChecked, setIsChecked] = React.useState(false);
            const [isSubmitted, setIsSubmitted] = React.useState(false);

            const handleCheckboxChange = (e) => {
                setIsChecked(e.target.checked);
            };

            const handleSubmit = (e) => {
                e.preventDefault();
                if (isChecked) {
                    setIsSubmitted(true);
                    setTimeout(() => {
                        alert('Thank you for accepting our terms of use.');
                        setIsSubmitted(false);
                        setIsChecked(false);
                    }, 500);
                }
            };

            return (
                <form className="consent-form" onSubmit={handleSubmit}>
                    <div className="form-container">
                        <h1>Terms of Use</h1>
                        <p className="intro-text">
                            Please review and accept our terms of use to continue.
                        </p>

                        <div className="form-field">
                            <label className="checkbox-label">
                                <input
                                    type="checkbox"
                                    checked={isChecked}
                                    onChange={handleCheckboxChange}
                                    required
                                    aria-required="true"
                                    className="checkbox-input"
                                />
                                <span className="checkbox-text">
                                    I agree to the Terms of Use
                                </span>
                            </label>
                            <p className="helper-text">
                                You must accept the terms to proceed.
                            </p>
                        </div>

                        <button
                            type="submit"
                            disabled={!isChecked}
                            className="submit-button"
                        >
                            Accept and Continue
                        </button>
                    </div>
                </form>
            );
        }

        // Mount component
        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ConsentForm />);
    </script>

    <!-- React and ReactDOM via CDN -->
    <script crossorigin src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

    <!-- Component rendering script (move after React scripts) -->
    <script type="text/babel" src="script.js"></script>
</body>
</html>
